document.addEventListener('DOMContentLoaded', function () {
  class V5ScrollVideoKv3 {
    constructor() {
      this.sectionId = '#v5ScrollVideoKv3';
      this.v5ScrollVideoKv3Trigger = null;
      this.section = document.querySelector(this.sectionId);

      // 动态生成 anchor
      const shopifySection = this.section.closest('.shopify-section');
      const anchorV5 = this.section.getAttribute('data-anchor-v5');
      if (shopifySection && anchorV5) {
        shopifySection.setAttribute('data-anchor-v5', anchorV5);
      }

      // 总数
      this.blockNum = this.section.getAttribute('data-block-num');
      if(this.blockNum === 0) return

      this.screen1Dom = this.section.querySelector('.screen-1')
      this.screen1Video =
        window.innerWidth > 1023
          ? this.screen1Dom.querySelector('.pc-video-wrap viewport-video')
          : this.screen1Dom.querySelector('.mb-video-wrap viewport-video');

      // 当前屏，默认为第一屏
      this.activeScreen = this.screen1Dom
      this.activeScreenVideo = this.screen1Video

      // 是否开始时间轴滚动监听
      this.startTimeLine = false;

      this.currDirection = null;

      this.init();
    }
    init() {
      // 两个视频时触发滚动动效
      if(this.blockNum > 1){
        this.scrollTimeLine();
        this.observeFunc();
      }
      this.checkIn();
      this.scrollListener();
    }
    checkIn(){
      const isIn = window.Jackery.Utils.isElementInViewport(this.section);
      const videoPlay = this.activeScreen.getAttribute('data-video-play');
      if (this.activeScreenVideo && isIn && videoPlay === 'false'){
        // 当前在视窗，开始播放
        this.activeScreenVideo.play();
        this.activeScreen.setAttribute('data-video-play','true')
      }
    }
    scrollListener() {
      // 添加状态记录变量
      let lastViewportState = null; // null: 初始状态, true: 在视口内, false: 在视口外
      const throttledScroll = window.throttle(() => {
        const isIn = window.Jackery.Utils.isElementInViewport(this.section);
        const currentState = isIn; // true: 在视口内, false: 在视口外

        // 只有状态发生变化时才执行
        if (lastViewportState === currentState) return;
        lastViewportState = currentState;

        if(self.blockNum > 1 && !this.startTimeLine) return

        const videoPlay = this.activeScreen.getAttribute('data-video-play');
        if (this.activeScreenVideo) {
          if (isIn) {
            if(videoPlay === 'false'){
              // 进入视窗，开始播放
              this.activeScreenVideo.togglePlayButton('hidden');
              this.activeScreenVideo.play();
              this.activeScreen.setAttribute('data-video-play','true')
            }
          } else {
            if(videoPlay === 'true'){
              // 不在视窗停止播放
              this.activeScreenVideo.pause();
              this.activeScreen.setAttribute('data-video-play','false')
            }
          }
        }
      }, 150);
      window.addEventListener('scroll', throttledScroll, { passive: true });
    }

    observeFunc(){
      const self = this;
      // 橱窗版块的DOM元素 需要持续监听
      const pdpInfoContainer = document.querySelector('.section-v5-main-product') || document.querySelector('.product-info-container');

      // 该组件需要持续监听
      const v5Accordion = document.querySelector('.section-v5-accordion');
      if (pdpInfoContainer || v5Accordion) {
        // 创建防抖函数来限制refresh频率
        const debouncedRefresh = window.throttle(() => {
          if (self.v5ScrollVideoKv3Trigger && typeof self.v5ScrollVideoKv3Trigger.refresh === 'function') {
            self.v5ScrollVideoKv3Trigger.refresh();
          }
          // 观察到变更后，启动/重置空闲期清理计时器
          // if(pdpInfoContainer){
          //   scheduleIdleCleanup();
          // }
        }, 100); // 100ms内最多执行一次

        // 创建ResizeObserver实例
        const observer = new ResizeObserver((entries) => {
          // 检查是否有实际的尺寸变化
          for (let entry of entries) {
            const { height } = entry.contentRect;
            // 只有当尺寸发生实际变化时才触发刷新
            if (height > 0) {
              debouncedRefresh();
              break;
            }
          }
        });

        // 在一段"空闲期"后自动清理，避免过早地 load 时断开监听
        let resizeIdleTimer = null;
        const scheduleIdleCleanup = () => {
          if (resizeIdleTimer) clearTimeout(resizeIdleTimer);
          resizeIdleTimer = setTimeout(() => {
            // 橱窗稳定，卸载监听
            cleanupObserver();
          }, 120000); // 2min，根据需要调整空闲期时长
        };

        // 开始观察元素尺寸变化
        [pdpInfoContainer, v5Accordion].forEach(element => {
          if (element) {
            observer.observe(element);
          }
        });

        // 断开观察
        const cleanupObserver = () => {
          if (observer) {
            observer.disconnect();
          }
          if (resizeIdleTimer) {
            clearTimeout(resizeIdleTimer);
            resizeIdleTimer = null;
          }
        };

        // 在页面隐藏或离开时清理，避免遗漏 load 之后生成的 DOM
        window.addEventListener('pagehide', cleanupObserver);
        document.addEventListener('visibilitychange', function () {
          if (document.visibilityState === 'hidden') cleanupObserver();
        });

        // 清理保障：当组件卸载时也应该断开观察
        if (window.Shopify && window.Shopify.designMode && this.section) {
          const parentSection = this.section.closest('.shopify-section');
          if (parentSection) {
            parentSection.addEventListener('section:unload', cleanupObserver);
          }
        }
      }
    }

    // 滚动动画
    scrollTimeLine() {
      if (!window._scrollTriggerRegistered) {
        window.gsap.registerPlugin(window.ScrollTrigger);
        window._scrollTriggerRegistered = true;
      }

      const self = this;
      let topH = '4.1666667vw';
      const productTabsBox = document.querySelector('.product-tabs-box,.section-navigation');
      if (productTabsBox) {
        topH = productTabsBox.offsetHeight + 'px';
      } else {
        const header = document.querySelector('jky-header,header-v5');
        topH = header.offsetHeight + 'px';
      }


      const screen2Dom = self.section.querySelector('.screen-2')
      const screen2Video = window.innerWidth > 1023 ? screen2Dom.querySelector('.pc-video-wrap viewport-video') : screen2Dom.querySelector('.mb-video-wrap viewport-video');

      let tl;
      // 储存实例动画已经进行了多长的时间
      const time = tl ? tl.time() : 0;
      if (tl) {
        tl.kill();
      }
      tl = window.gsap.timeline({ paused: true });
      self.v5ScrollVideoKv3Trigger = window.ScrollTrigger.create({
        trigger: self.sectionId,
        pin: true, // 将触发元素固定，在激活时
        start: `top ${topH}`, // 当触发元素的顶部碰到视口顶部时
        end: `+=200`, // 在起始位置滚动 xxx 后结束
        scrub: 1, // 平滑擦洗，需要1秒钟来“赶上”滚动条
        // markers: true,
        snap: [0,1],
        onUpdate: curr => {
          // 记录当前滚动方向
          self.currDirection = curr.direction;

          // 向上回滚页面
          if (curr.direction === -1) {
            if(curr.progress.toFixed(2) === '0.00'){
              const videoPlay = self.screen1Dom.getAttribute('data-video-play');
              if (videoPlay === 'false' && self.screen1Video) {
                // 页面回滚到第一屏，开始播放视频
                self.screen1Video.play();
                self.screen1Dom.setAttribute('data-video-play', 'true');
                self.activeScreen = self.screen1Dom;
                self.activeScreenVideo = self.screen1Video;

                screen2Video?.pause();
                screen2Dom?.setAttribute('data-video-play', 'false');
              }
            } else if(curr.progress.toFixed(2) === '0.66'){
              const videoPlay = screen2Dom.getAttribute('data-video-play');
              if (videoPlay === 'false' && screen2Video) {
                // 页面回滚到第二屏，开始播放视频
                screen2Video.play();
                screen2Dom.setAttribute('data-video-play', 'true');
                self.activeScreen = screen2Dom;
                self.activeScreenVideo = screen2Video;
              }
            }

          }
        },
        animation: tl,
      });


      // 动效
      tl.addLabel('screen-1')
        .to('.v5-scroll-video-kv-3 .screen-1 .content-wrapper', {
          y: 0,
          ease: 'power4.in',
          duration: 0.01,
          onComplete: () => {
            if (self.screen1Video) {
              self.activeScreen = self.screen1Dom;
              self.activeScreenVideo = self.screen1Video;
              self.startTimeLine = true
            }
          }
        })

        tl.addLabel('screen-2')
          .to('.v5-scroll-video-kv-3 .screen-1 .content-wrapper', {
            y:'-100%',
            opacity: 0,
            ease: 'power4.in',
            duration: 0.39,
            onComplete: () => {
              if (self.screen1Video) {
                self.screen1Video.pause();
                self.screen1Dom.setAttribute('data-video-play', 'false');
              }
            }
          },'screen-2')
          .to('.v5-scroll-video-kv-3 .screen-2', {
            opacity: 1,
            ease: 'none',
            duration: 0.4
          },'screen-2')
          .to('.v5-scroll-video-kv-3 .screen-2 .content-wrapper', {
            y: `-100%`,
            ease: 'power4.in',
            duration: 0.39,
            onUpdate: () => {
              if(self.currDirection === 1) return;
              const videoPlay = screen2Dom.getAttribute('data-video-play');
              if (videoPlay === 'true' && screen2Video) {
                // 停止播放第二屏视频
                screen2Video.pause();
                screen2Dom.setAttribute('data-video-play', 'false');
              }
            },
            onComplete: () => {
              // 第二屏执行完成，播放视频
              if (screen2Video) {
                screen2Video.play();
                screen2Dom.setAttribute('data-video-play', 'true');
                self.activeScreen = screen2Dom;
                self.activeScreenVideo = screen2Video;
              }
            },
          },'screen-2')
          .to('.v5-scroll-video-kv-3 .screen-1 .content-wrapper', {
            visibility: 'visible',
            ease: 'none',
            duration: 0.1
          },'>')

      tl.time(time);
    }
  }
  new V5ScrollVideoKv3();
});